using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.UIElements;using TMPro;using Abyss.Story;
public static class VoyageFinalFlowCheck {
 static Stack<IEnumerator> tasks;static string report;static double deadline;static int errors;
 public static void Begin(){Directory.CreateDirectory("Tools/FinalFlowUpdate");report="Latest campaign, loot and fonts - Play Mode integration\nRuntime-only accelerated purifier and actor placement for scene boundaries.\n";errors=0;deadline=EditorApplication.timeSinceStartup+180;tasks=new();tasks.Push(Run());Application.logMessageReceived+=Log;EditorApplication.update+=Tick;EditorWindow.GetWindow(typeof(EditorWindow).Assembly.GetType("UnityEditor.GameView")).Focus();}
 static void Log(string m,string s,LogType t){if(t==LogType.Error||t==LogType.Exception)errors++;}
 static void Tick(){Application.runInBackground=true;EditorApplication.QueuePlayerLoopUpdate();try{if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Timeout");if(tasks.Count==0){End();return;}var item=tasks.Peek();if(!item.MoveNext()){tasks.Pop();return;}if(item.Current is IEnumerator child)tasks.Push(child);else if(item.Current is AsyncOperation op)tasks.Push(Operation(op));}catch(Exception e){report+="FAIL "+e+"\n";End();}}
 static void End(){File.WriteAllText("Tools/FinalFlowUpdate/check.txt",report);Application.logMessageReceived-=Log;EditorApplication.update-=Tick;}
 static void Check(bool value,string message){report+=(value?"PASS ":"FAIL ")+message+"\n";File.WriteAllText("Tools/FinalFlowUpdate/check.txt",report);if(!value)throw new Exception(message);}
 static IEnumerator Wait(float seconds){double until=EditorApplication.timeSinceStartup+seconds;while(EditorApplication.timeSinceStartup<until)yield return null;}
 static IEnumerator Operation(AsyncOperation op){while(!op.isDone)yield return null;}
 static IEnumerator ShipTalk(){double until=EditorApplication.timeSinceStartup+8;while(EditorApplication.timeSinceStartup<until){var d=UnityEngine.Object.FindFirstObjectByType<ShipVisitDialogue>();if(d&&d.ReadyForGameplay)yield break;if(d&&d.UI.Active)d.UI.Advance();yield return null;}throw new Exception("Ship talk did not finish");}
 static IEnumerator FinishVisit(JourneyStage next){var ship=UnityEngine.Object.FindFirstObjectByType<ShipController>();ship.enabled=false;var rb=ship.GetComponent<Rigidbody2D>();rb.position=new Vector2(30,0);rb.rotation=0;var water=ship.GetComponent<ShipWaterPurification>();water.forwardDistanceForFull=1;water.RestoreProgress(.999f);rb.linearVelocity=Vector2.up*10;double until=EditorApplication.timeSinceStartup+12;while(EditorApplication.timeSinceStartup<until){var d=UnityEngine.Object.FindFirstObjectByType<ShipVisitDialogue>();if(d&&d.UI.Active)d.UI.Advance();if(StorySceneJourney.Instance.Stage==next&&!StorySceneJourney.Instance.IsTransitioning){yield return Wait(.6f);yield break;}yield return null;}throw new Exception("Expected visit "+next);}
 static void Move(UnderwaterDayStory story,Vector2 at){story.player.transform.position=at;story.player.GetComponent<Rigidbody2D>().position=at;Physics2D.SyncTransforms();}
 static IEnumerator Run(){
 Time.timeScale=1;yield return SceneManager.LoadSceneAsync("MainMenu");yield return Wait(.3f);var video=UnityEngine.Object.FindFirstObjectByType<UnityEngine.Video.VideoPlayer>();if(video){double end=EditorApplication.timeSinceStartup+10;while(!video.isPrepared&&EditorApplication.timeSinceStartup<end)yield return null;if(video)video.time=Math.Max(0,video.length-.1);yield return Wait(2.5f);}var music=UnityEngine.Object.FindFirstObjectByType<VoyageMusic>();yield return Wait(1);Check(music.GetComponents<AudioSource>().Any(a=>a.isPlaying&&a.clip&&a.clip.name=="underwater"),"Menu score plays in menu");
 StorySceneJourney.Instance.NewGame();yield return Wait(2);var story=UnityEngine.Object.FindFirstObjectByType<UnderwaterDayStory>();Check(story&&StorySceneJourney.Instance.Stage==JourneyStage.FirstUnderwater,"New Game begins with original underwater discovery");Check(!music.GetComponents<AudioSource>().Any(a=>a.isPlaying),"No menu music leaks into first underwater chapter");story.ui.Clear();typeof(UnderwaterDayStory).GetField("stage",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(story,UnderwaterDayStage.Completed);Move(story,story.playerHome.bounds.center);story.secondChapter.RequestHomeEntry();yield return Wait(1);Check(StorySceneJourney.Instance.Stage==JourneyStage.FirstShip,"Completed discovery and home entry reach first ship visit");yield return ShipTalk();var ship=UnityEngine.Object.FindFirstObjectByType<ShipController>();Check(!UnityEngine.Object.FindFirstObjectByType<EnemySpawner>().enabled&&UnityEngine.Object.FindObjectsByType<Enemy>(FindObjectsSortMode.None).Length==0,"First ship visit has no initial attack");yield return Wait(2.2f);Check(UnityEngine.Object.FindObjectsByType<Enemy>(FindObjectsSortMode.None).Length==0&&ship.energyDrainRate>0&&ship.GetComponent<PeacefulEnergyField>(),"Peaceful visit stays attack-free with energy consumption and sea energy pickups");yield return FinishVisit(JourneyStage.SecondUnderwater);yield return Wait(1.3f);story=UnityEngine.Object.FindFirstObjectByType<UnderwaterDayStory>();Check(story&&story.secondChapter.Stage==SecondChapterStage.AttendAnnouncement,"First 100% purification starts the announcement chapter");Check(!music.GetComponents<AudioSource>().Any(a=>a.isPlaying),"Announcement chapter has no music score");story.ui.Clear();Move(story,story.secondChapter.meetingPoint);story.secondChapter.Interact();double announce=EditorApplication.timeSinceStartup+10;while(story.secondChapter.Stage!=SecondChapterStage.LeaveForSharks&&EditorApplication.timeSinceStartup<announce){if(story.ui.Active)story.ui.Advance();yield return null;}Check(story.secondChapter.Stage==SecondChapterStage.LeaveForSharks,"Existing president attack decision finishes before first combat");story.ui.Clear();Move(story,new Vector2(story.secondChapter.departurePoint.x,-25));story.secondChapter.Tick();yield return Wait(1);Check(StorySceneJourney.Instance.Stage==JourneyStage.ShipBattle,"Leaving toward sharks starts the small-fish ship attack");yield return ShipTalk();ship=UnityEngine.Object.FindFirstObjectByType<ShipController>();ship.transform.position=new Vector3(HarborAttackGate.DepartureX+3,0,0);ship.GetComponent<Rigidbody2D>().position=ship.transform.position;yield return Wait(.2f);typeof(PlayerHealth).GetProperty("IsInvulnerable").SetValue(ship.GetComponent<PlayerHealth>(),true);var ui=UnityEngine.Object.FindFirstObjectByType<ShipUIManager>();var spawner=UnityEngine.Object.FindFirstObjectByType<EnemySpawner>();Check(spawner.enabled&&spawner.selectedEnemyPrefabs.All(p=>!p.name.Contains("Shark")&&!p.name.Contains("Whale")&&!p.name.Contains("Orca")),"First combat produces only small fish");
 Time.timeScale=0;ship.GetComponent<ShipWeapons>().enabled=false;foreach(var b in UnityEngine.Object.FindObjectsByType<Bullet>(FindObjectsSortMode.None))UnityEngine.Object.Destroy(b.gameObject);foreach(var oldLoot in UnityEngine.Object.FindObjectsByType<Loot>(FindObjectsSortMode.None))UnityEngine.Object.Destroy(oldLoot.gameObject);yield return Wait(.15f);var enemy=UnityEngine.Object.FindObjectsByType<Enemy>(FindObjectsSortMode.None).First();enemy.TakeDamage(99999,ship.transform.position);yield return Wait(.15f);var loot=UnityEngine.Object.FindFirstObjectByType<Loot>();Check(loot&&loot.GetComponent<ShipLootVisual>().CurrentIcon==Resources.Load<Sprite>("Voyage/loot_star"),"Actual fish kill drops the HUD-style XP star");ui.ToggleLootMode();yield return Wait(.1f);Check(loot.GetComponent<ShipLootVisual>().CurrentIcon==Resources.Load<Sprite>("Voyage/loot_energy"),"Changing reward selection shows a lightning pickup");ship.currentEnergy=50;float energyReward=loot.energyValue;float xp=ui.currentXP;loot.transform.position=ship.transform.position;Time.timeScale=1;yield return Wait(.12f);Check(ship.currentEnergy==50+energyReward&&ui.currentXP==xp,"Lightning pickup grants only existing energy value; energy="+ship.currentEnergy+", xp="+ui.currentXP);
 ui.ToggleLootMode();Time.timeScale=0;enemy=UnityEngine.Object.FindObjectsByType<Enemy>(FindObjectsSortMode.None).First();enemy.TakeDamage(99999,ship.transform.position);yield return Wait(.15f);loot=UnityEngine.Object.FindFirstObjectByType<Loot>();ui.currentXP=ui.nextLevelXP-1;loot.transform.position=ship.transform.position;Time.timeScale=1;yield return Wait(.15f);Check(ui.currentLevel==2&&ui.levelText&&ui.levelText.name=="LevelValue"&&ui.levelText.text=="2","Actual star pickup levels up and updates the visible top-left badge");Check(ui.levelText.font.name=="PixelNumbers"&&ui.levelText.font.HasCharacter('2')&&ui.levelText.font.atlasRenderMode==UnityEngine.TextCore.LowLevel.GlyphRenderMode.SDFAA,"HUD numbers use a baked pixel font with valid digits");var document=ui.levelUpDocument.rootVisualElement;Check(document.Query<Label>().ToList().All(l=>l.resolvedStyle.unityFontDefinition.font==Resources.Load<Font>("Voyage/PixelifySans")),"All selection labels, descriptions and numbers share the pixel font");ScreenCapture.CaptureScreenshot("Tools/FinalFlowUpdate/level-and-fonts.png");yield return Wait(.2f);ui.OnCardClicked(0);yield return FinishVisit(JourneyStage.ThirdUnderwater);yield return Wait(1.4f);story=UnityEngine.Object.FindFirstObjectByType<UnderwaterDayStory>();Check(story.thirdChapter.Started&&story.thirdChapter.hazards.Running,"Second 100% purification returns to the cannon-dodging shark journey");yield return Wait(1);Check(music.GetComponents<AudioSource>().Any(a=>a.isPlaying&&a.clip&&a.clip.name=="danger"),"TopSUalti plays specifically during the shark journey");story.ui.Clear();Move(story,story.thirdChapter.leader.Position);story.thirdChapter.Interact();double help=EditorApplication.timeSinceStartup+12;while(!story.thirdChapter.Complete&&EditorApplication.timeSinceStartup<help){if(story.ui.Active)story.ui.Advance();if(story.thirdChapter.Stage==ThirdChapterStage.Rally){story.thirdChapter.leader.Place(story.thirdChapter.rallyPositions[0]);for(int i=0;i<story.thirdChapter.guards.Length;i++)story.thirdChapter.guards[i].Place(story.thirdChapter.rallyPositions[i+1]);}yield return null;}yield return Wait(1);Check(StorySceneJourney.Instance.Stage==JourneyStage.SharkBattle,"Shark agreement returns to the final combined ship battle");ship=UnityEngine.Object.FindFirstObjectByType<ShipController>();ui=UnityEngine.Object.FindFirstObjectByType<ShipUIManager>();Check(ui.currentLevel==2&&ui.levelText.text=="2"&&ship.GetComponent<ShipWaterPurification>().NormalizedProgress==0,"Final visit retains prior level and resets purification");yield return ShipTalk();ship.transform.position=new Vector3(HarborAttackGate.DepartureX+3,0,0);ship.GetComponent<Rigidbody2D>().position=ship.transform.position;yield return Wait(.2f);typeof(PlayerHealth).GetProperty("IsInvulnerable").SetValue(ship.GetComponent<PlayerHealth>(),true);ship.enabled=false;ship.GetComponent<Rigidbody2D>().linearVelocity=Vector2.zero;spawner=UnityEngine.Object.FindFirstObjectByType<EnemySpawner>();Check(spawner.selectedEnemyPrefabs.Any(p=>p.name.Contains("Shark"))&&!spawner.selectedEnemyPrefabs.Any(p=>p.name.Contains("Whale")),"Final battle begins with small fish and sharks only");var water=ship.GetComponent<ShipWaterPurification>();int handle=SceneManager.GetActiveScene().handle;water.RestoreProgress(.199f);yield return Wait(.15f);Check(!spawner.selectedEnemyPrefabs.Any(p=>p.name.Contains("Whale")),"Whales remain absent below 20% purification");water.RestoreProgress(.2f);yield return Wait(.15f);var dialogue=ship.GetComponent<ShipVisitDialogue>();Check(dialogue.UI.Active&&dialogue.UI.CurrentText.Contains("Balinalar"),"20% purification opens the whale-attack textbox");ScreenCapture.CaptureScreenshot("Tools/FinalFlowUpdate/whales-join.png");yield return Wait(.2f);yield return ShipTalk();Check(SceneManager.GetActiveScene().handle==handle&&StorySceneJourney.Instance.Stage==JourneyStage.SharkBattle&&water.NormalizedProgress>=.2f,"Whales join the same battle without a scene reload or water reset");Check(spawner.selectedEnemyPrefabs.Any(p=>p.name.Contains("Whale"))&&UnityEngine.Object.FindObjectsByType<Enemy>(FindObjectsSortMode.None).Any(e=>e.name.Contains("Whale")),"Native producer admits whales and spawns the first reinforcement");Check(UnityEngine.Object.FindFirstObjectByType<InfiniteOcean>().pollution==.92f,"Final combined battle keeps the sea heavily polluted");water.RestoreProgress(.35f);yield return Wait(.15f);Check(!dialogue.UI.Active,"Whale arrival announcement fires once");yield return FinishVisit(JourneyStage.Finale);double ending=EditorApplication.timeSinceStartup+8;while(!GameObject.Find("Epilogue")&&EditorApplication.timeSinceStartup<ending){if(dialogue&&dialogue.UI.Active)dialogue.UI.Advance();yield return null;}Check(GameObject.Find("White flag • ending only")&&GameObject.Find("Epilogue"),"Combined battle ends with white flag, departure and final text");ScreenCapture.CaptureScreenshot("Tools/FinalFlowUpdate/ending.png");yield return Wait(9.5f);Check(SceneManager.GetActiveScene().name=="MainMenu"&&Time.timeScale==1,"Final text returns automatically to the main menu");Check(errors==0,"No runtime errors in current verification");
 }
}
